'use strict';self.window=self;
importScripts('../vendor/json5.min.js','../vendor/pako-jszip.min.js','../vendor/haxball.js','../stadiums/bff-big-v4.js','policy.js','selfplay.js','learning.js');
function makeRoom(callbacks={}){let time=0,id=0;const frames=new Map(),win={...self,performance:{now:()=>time},setTimeout,clearTimeout,setInterval,clearInterval,requestAnimationFrame:f=>{frames.set(++id,f);return id;},cancelAnimationFrame:i=>frames.delete(i)};const API=abcHaxballAPI(win),room=API.Room.sandbox(callbacks);return{room,reverse:API.Utils.reverseKeyState,map:name=>name==='BFF'?API.Utils.parseStadium(JSON.stringify(self.BFF_STADIUM)):API.Utils.getDefaultStadiums().find(s=>s.name==='Classic'),step:n=>{for(let i=0;i<n;i++){time+=1000/60;const pending=[...frames.values()];frames.clear();pending.forEach(f=>f(time));}}};}
self.onmessage=async({data})=>{try{const result=await FuckballSelfPlay.train(makeRoom,data,p=>postMessage({type:'progress',...p}));const splits={train:[],validation:[],test:[]};for(let i=0;i<6;i++){const split=i<4?'train':i===4?'validation':'test';FuckballSelfPlay.match(makeRoom,result.profile,result.profile,i%2+1,700001+i,'BFF',1800,row=>splits[split].push(row),data.model);postMessage({type:'progress',percent:100,text:'HaxLab training data '+(i+1)+' / 6'});await new Promise(r=>setTimeout(r,0));}const model=await FuckballLearning.train(splits,FuckballAI.columns,p=>postMessage({type:'progress',percent:p.percent,text:'Neural training '+p.epoch+' / '+p.epochs}),{epochs:8});model.name='HaxLab 4v4 Self-play';model.source_kind='self-play-team-teacher';model.training.split='whole simulated matches';postMessage({type:'done',result,model});}catch(e){postMessage({type:'error',message:e.message});}};
